    {
      V: 8,
      edges: [
        [0, 1],
        [1, 2],
        [2, 3],
        [0, 2],
        [0, 4],
        [2, 6],
        [3, 7],
        [2, 7],
        [4, 5],
        [5, 6],
        [6, 7],
      ],
      want: 2,
    },
    // Edge case: Single node.
    {
      V: 1,
      edges: [],
      want: 0,
    },
    // Can do 0 -> 1 or 2 -> 1.
    {
      V: 3,
      edges: [
        [0, 1],
        [1, 2],
      ],
      want: 1,
    },
    // Cycle graph.
    {
      V: 4,
      edges: [
        [0, 1],
        [1, 2],
        [2, 3],
        [3, 0],
      ],
      want: 0,
    },
    // Star graph.
    {
      V: 4,
      edges: [
        [0, 1],
        [0, 2],
        [0, 3],
      ],
      want: 1,
    },
    // Can do 3 -> 2 -> 1 -> 0.
    {
      V: 10,
      edges: [
        [0, 1],
        [1, 2],
        [2, 3],
        [2, 4],
        [3, 5],
        [3, 6],
        [3, 7],
      ],
      want: 3,
    },
  ];

  for (const { V, edges, want } of tests) {
    const got = longestPathOfIncreasingDegrees(V, edges);
    if (got !== want) {
      throw new Error(
        `\nlongestPathOfIncreasingDegrees(${V}, ${JSON.stringify(edges)}): ` +
          `got: ${got}, want: ${want}\n`,
      );
    }
  }
}

